head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setVal1 = function() {
    scwin.simulateWrapper('#G_wq_uuid_4__col1', 'key-combo', {
        combo: 'ESC'
    });
}
scwin.setVal2 = function() {
    scwin.simulateWrapper('#G_wq_uuid_4__col1', 'key-combo', {
        combo: 'ESC'
    });
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wq_uuid_4_cell_0_0')");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'wq_uuid_4__col1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'wq_uuid_4_cell_2_0')");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
    WebSquare.wUnit.addCommand('pause', '500');
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('G_'+$p.id+'wq_uuid_4__col1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand('pause', '500');
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /*
        그리드 뷰 cell의 dataType="float" 일 경우 포커스가 깜빡거릴 때 ESC로 포커스가 빠지지 않는 현상
        float : 데이터 없을경우 esc안됨, 데이터 있고 블록시 esc 안됨, 데이터 있고 포커스시 esc 됨.
        number : 데이터 없을경우 esc됨, 데이터 있고 블록시 esc 됨, 데이터 있고 포커스시 esc 됨.
        text : 데이터 없을경우 esc됨, 데이터 있고 블록시 esc 됨, 데이터 있고 포커스시 esc 됨.

     */
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
